114	        Page<Post> coursePosts;
115	
116	        final var requestingUser = userRepository.getUserWithGroupsAndAuthorities();
117	        final var course = courseRepository.findByIdElseThrow(postContextFilter.courseId());
118	        authorizationCheckService.checkHasAtLeastRoleInCourseElseThrow(Role.STUDENT, course, requestingUser);
119	
120	        if (postContextFilter.conversationId() != null) {
121	            coursePosts = conversationMessagingService.getMessages(pageable, postContextFilter, requestingUser, course.getId());
122	        }
123	        else if (postContextFilter.courseWideChannelIds() != null) {
124	            coursePosts = conversationMessagingService.getCourseWideMessages(pageable, postContextFilter, requestingUser, course.getId());
