129	        // keep the data as small as possible and avoid unnecessary information sent to the client
130	        // TODO: in the future we should use a DTO and send only the necessary information
131	        coursePosts.getContent().forEach(post -> {
132	            if (post.getConversation() != null) {
133	                post.getConversation().hideDetails();
