75	     * @return specification used to chain DB operations
76	     */
77	    public static Specification<Post> getConversationsSpecification(long[] conversationIds) {
78	        return ((root, query, criteriaBuilder) -> {
79	            if (conversationIds == null || conversationIds.length == 0) {
80	                return null;
81	            }
82	            else {
83	                return root.get(Post_.CONVERSATION).get(Conversation_.ID).in(Arrays.stream(conversationIds).boxed().toList());
84	            }
85	        });
86	    }
